<?php
namespace App\Http\Controllers; use App\Domain\WorkProcesses\{WorkProcessIndexViewData,WorkProcessViewData}; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; class PublicWorkProcessController extends Controller { public function index(Request $request,WorkProcessIndexViewData $data):View{return view('work-processes.index',['processes'=>$data->get(max(1,$request->integer('page',1)))]+app(PublicSiteController::class)->sharedViewData($request));} public function show(Request $request,string $workProcess,WorkProcessViewData $data):View{$item=$data->published($workProcess);if(!$item)abort(404);return view('work-processes.show',['process'=>$item,'preview'=>false]+app(PublicSiteController::class)->sharedViewData($request));} }
